/// Median of a slice, `None` when empty. Copies to sort — the
/// slices are batch counts, not sample counts.
fn median(v: &[f64]) -> Option<f64> {
    if v.is_empty() {
        return None;
    }
    let mut s = v.to_vec();
    s.sort_by(f64::total_cmp);
    Some(s[s.len() / 2])
}

